index = 1
while index < len(lines) - 1:
    header = lines[index]
    if header.startswith('*** Update File: '):
        path = pathlib.Path(header[len('*** Update File: '):])
        text = path.read_text()
        index += 1
        while index < len(lines) - 1 and not lines[index].startswith('*** '):
            if not lines[index].startswith('@@'):
                raise SystemExit(f'expected hunk header, got {lines[index]!r}')
            index += 1
            old = []
            new = []
            while index < len(lines) - 1 and not lines[index].startswith('@@') and not lines[index].startswith('*** '):
                line = lines[index]
                if line.startswith(' '):
                    old.append(line[1:])
                    new.append(line[1:])
                elif line.startswith('-'):
                    old.append(line[1:])
                elif line.startswith('+'):
                    new.append(line[1:])
                else:
                    raise SystemExit(f'invalid hunk line {line!r}')
                index += 1
            old_text = '\n'.join(old)
            new_text = '\n'.join(new)
            if old_text not in text:
                raise SystemExit(f'context not found in {path}:\n{old_text}')
            text = text.replace(old_text, new_text, 1)
        path.write_text(text)
    elif header.startswith('*** Add File: '):
        path = pathlib.Path(header[len('*** Add File: '):])
        index += 1
        content = []
        while index < len(lines) - 1 and not lines[index].startswith('*** '):
            line = lines[index]
            if not line.startswith('+'):
                raise SystemExit(f'invalid add line {line!r}')
            content.append(line[1:])
            index += 1
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('\n'.join(content) + '\n')
    else:
        raise SystemExit(f'unsupported patch header {header!r}')
